namespace sv_71482aced68343b79d282c75d8a11d69.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public sealed class ThemePreferences
{
    public Theme Theme { get; set; } = Theme.System;
    public string AccentColor { get; set; } = "#0d6efd";
}

/// <summary>
/// Scoped service — shared by all interactive components within a single circuit.
/// In per-page interactivity mode every interactive island on the same page shares
/// one circuit, so they all see the same ThemeService instance and receive change
/// notifications via <see cref="OnThemeChanged"/>.
///
/// Persistence across navigations (which create new circuits) is handled by
/// reading/writing browser localStorage through the companion theme.js module.
/// </summary>
public sealed class ThemeService
{
    public ThemePreferences Current { get; private set; } = new();

    public event Action? OnThemeChanged;

    public void SetTheme(Theme theme)
    {
        Current.Theme = theme;
        OnThemeChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        Current.AccentColor = color;
        OnThemeChanged?.Invoke();
    }

    public void Apply(ThemePreferences prefs)
    {
        Current = prefs;
        OnThemeChanged?.Invoke();
    }

    /// <summary>
    /// Hydrate from values read out of localStorage (no event fired — this is
    /// the initial load, not a user-initiated change).
    /// </summary>
    public void Hydrate(Theme theme, string accentColor)
    {
        Current.Theme = theme;
        Current.AccentColor = accentColor;
    }
}

const STORAGE_KEY = "app-theme-prefs";

const defaults = { theme: "System", accentColor: "#0d6efd" };

function read() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? { ...defaults, ...JSON.parse(raw) } : { ...defaults };
    } catch {
        return { ...defaults };
    }
}

function write(prefs) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
}

function applyToDocument(prefs) {
    const root = document.documentElement;

    // Resolve effective theme (respect OS preference for "System")
    let effective = prefs.theme;
    if (effective === "System") {
        effective = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "Dark"
            : "Light";
    }

    root.setAttribute("data-bs-theme", effective.toLowerCase());
    root.style.setProperty("--app-accent", prefs.accentColor);
}

// --- Blazor JS interop entry points (called from C#) ---

export function getPreferences() {
    return read();
}

export function setPreferences(theme, accentColor) {
    const prefs = { theme, accentColor };
    write(prefs);
    applyToDocument(prefs);
}

// Apply saved theme immediately on script load to avoid FOUC
applyToDocument(read());

// Re-evaluate "System" theme when OS preference changes
window.matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", () => {
        const prefs = read();
        if (prefs.theme === "System") {
            applyToDocument(prefs);
        }
    });

@using sv_71482aced68343b79d282c75d8a11d69.Services
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.Current.AccentColor;">
    @icon @ThemeService.Current.Theme
</span>

@code {
    private IJSObjectReference? module;
    private string icon => ThemeService.Current.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.Light => "☀️",
        _ => "💻"
    };

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "/js/theme.js");

            var prefs = await module.InvokeAsync<ThemePrefs>("getPreferences");
            ThemeService.Hydrate(
                Enum.Parse<Theme>(prefs.Theme, ignoreCase: true),
                prefs.AccentColor);
            StateHasChanged();

            ThemeService.OnThemeChanged += HandleThemeChanged;
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(async () =>
        {
            if (module is not null)
            {
                await module.InvokeVoidAsync("setPreferences",
                    ThemeService.Current.Theme.ToString(),
                    ThemeService.Current.AccentColor);
            }
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }

    private sealed record ThemePrefs(string Theme, string AccentColor);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_71482aced68343b79d282c75d8a11d69.Services
@inject ThemeService ThemeService
@inject IJSRuntime JS

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5 class="card-title">Theme</h5>

    <div class="btn-group mb-3" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <button class="btn @(t == selectedTheme ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SelectTheme(t)">
                @t
            </button>
        }
    </div>

    <h5 class="card-title">Accent Color</h5>

    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@accentColor"
               @onchange="OnAccentChanged" />
        <span style="color: @accentColor; font-weight: bold;">@accentColor</span>
    </div>

    <div class="alert alert-info mb-0">
        Changes are applied instantly to all components on the page.
    </div>
</div>

@code {
    private Theme selectedTheme;
    private string accentColor = "#0d6efd";
    private IJSObjectReference? module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "/js/theme.js");

            var prefs = await module.InvokeAsync<ThemePrefs>("getPreferences");
            ThemeService.Hydrate(
                Enum.Parse<Theme>(prefs.Theme, ignoreCase: true),
                prefs.AccentColor);

            selectedTheme = ThemeService.Current.Theme;
            accentColor = ThemeService.Current.AccentColor;
            StateHasChanged();
        }
    }

    private void SelectTheme(Theme theme)
    {
        selectedTheme = theme;
        ThemeService.SetTheme(theme);
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? accentColor;
        ThemeService.SetAccentColor(accentColor);
    }

    private sealed record ThemePrefs(string Theme, string AccentColor);
}

namespace sv_71482aced68343b79d282c75d8a11d69.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public sealed class ThemePreferences
{
    public Theme Theme { get; set; } = Theme.System;
    public string AccentColor { get; set; } = "#0d6efd";
}

/// <summary>
/// Scoped service — shared by all interactive components within a single circuit.
/// In per-page interactivity mode every interactive island on the same page shares
/// one circuit, so they all see the same ThemeService instance and receive change
/// notifications via <see cref="OnThemeChanged"/>.
///
/// Persistence across navigations (which create new circuits) is handled by
/// reading/writing browser localStorage through the companion theme.js module.
/// </summary>
public sealed class ThemeService
{
    public ThemePreferences Current { get; private set; } = new();

    public event Action? OnThemeChanged;

    public void SetTheme(Theme theme)
    {
        Current.Theme = theme;
        OnThemeChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        Current.AccentColor = color;
        OnThemeChanged?.Invoke();
    }

    public void Apply(ThemePreferences prefs)
    {
        Current = prefs;
        OnThemeChanged?.Invoke();
    }

    /// <summary>
    /// Hydrate from values read out of localStorage (no event fired — this is
    /// the initial load, not a user-initiated change).
    /// </summary>
    public void Hydrate(Theme theme, string accentColor)
    {
        Current.Theme = theme;
        Current.AccentColor = accentColor;
    }
}

const STORAGE_KEY = "app-theme-prefs";

const defaults = { theme: "System", accentColor: "#0d6efd" };

function read() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? { ...defaults, ...JSON.parse(raw) } : { ...defaults };
    } catch {
        return { ...defaults };
    }
}

function write(prefs) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
}

function applyToDocument(prefs) {
    const root = document.documentElement;

    // Resolve effective theme (respect OS preference for "System")
    let effective = prefs.theme;
    if (effective === "System") {
        effective = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "Dark"
            : "Light";
    }

    root.setAttribute("data-bs-theme", effective.toLowerCase());
    root.style.setProperty("--app-accent", prefs.accentColor);
}

// --- Blazor JS interop entry points (called from C#) ---

export function getPreferences() {
    return read();
}

export function setPreferences(theme, accentColor) {
    const prefs = { theme, accentColor };
    write(prefs);
    applyToDocument(prefs);
}

// Apply saved theme immediately on script load to avoid FOUC
applyToDocument(read());

// Re-evaluate "System" theme when OS preference changes
window.matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", () => {
        const prefs = read();
        if (prefs.theme === "System") {
            applyToDocument(prefs);
        }
    });

@using sv_71482aced68343b79d282c75d8a11d69.Services
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.Current.AccentColor;">
    @icon @ThemeService.Current.Theme
</span>

@code {
    private IJSObjectReference? module;
    private string icon => ThemeService.Current.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.Light => "☀️",
        _ => "💻"
    };

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "/js/theme.js");

            var prefs = await module.InvokeAsync<ThemePrefs>("getPreferences");
            ThemeService.Hydrate(
                Enum.Parse<Theme>(prefs.Theme, ignoreCase: true),
                prefs.AccentColor);
            StateHasChanged();

            ThemeService.OnThemeChanged += HandleThemeChanged;
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(async () =>
        {
            if (module is not null)
            {
                await module.InvokeVoidAsync("setPreferences",
                    ThemeService.Current.Theme.ToString(),
                    ThemeService.Current.AccentColor);
            }
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }

    private sealed record ThemePrefs(string Theme, string AccentColor);
}

