@page "/settings"
@rendermode InteractiveServer
@using sv_71482aced68343b79d282c75d8a11d69.Services
@inject ThemeService ThemeService
@inject IJSRuntime JS

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5 class="card-title">Theme</h5>

    <div class="btn-group mb-3" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <button class="btn @(t == selectedTheme ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SelectTheme(t)">
                @t
            </button>
        }
    </div>

    <h5 class="card-title">Accent Color</h5>

    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@accentColor"
               @onchange="OnAccentChanged" />
        <span style="color: @accentColor; font-weight: bold;">@accentColor</span>
    </div>

    <div class="alert alert-info mb-0">
        Changes are applied instantly to all components on the page.
    </div>
</div>

@code {
    private Theme selectedTheme;
    private string accentColor = "#0d6efd";
    private IJSObjectReference? module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "/js/theme.js");

            var prefs = await module.InvokeAsync<ThemePrefs>("getPreferences");
            ThemeService.Hydrate(
                Enum.Parse<Theme>(prefs.Theme, ignoreCase: true),
                prefs.AccentColor);

            selectedTheme = ThemeService.Current.Theme;
            accentColor = ThemeService.Current.AccentColor;
            StateHasChanged();
        }
    }

    private void SelectTheme(Theme theme)
    {
        selectedTheme = theme;
        ThemeService.SetTheme(theme);
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? accentColor;
        ThemeService.SetAccentColor(accentColor);
    }

    private sealed record ThemePrefs(string Theme, string AccentColor);
}

