const STORAGE_KEY = "app-theme-prefs";

const defaults = { theme: "System", accentColor: "#0d6efd" };

function read() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? { ...defaults, ...JSON.parse(raw) } : { ...defaults };
    } catch {
        return { ...defaults };
    }
}

function write(prefs) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
}

function applyToDocument(prefs) {
    const root = document.documentElement;

    // Resolve effective theme (respect OS preference for "System")
    let effective = prefs.theme;
    if (effective === "System") {
        effective = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "Dark"
            : "Light";
    }

    root.setAttribute("data-bs-theme", effective.toLowerCase());
    root.style.setProperty("--app-accent", prefs.accentColor);
}

// --- Blazor JS interop entry points (called from C#) ---

export function getPreferences() {
    return read();
}

export function setPreferences(theme, accentColor) {
    const prefs = { theme, accentColor };
    write(prefs);
    applyToDocument(prefs);
}

// Apply saved theme immediately on script load to avoid FOUC
applyToDocument(read());

// Re-evaluate "System" theme when OS preference changes
window.matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", () => {
        const prefs = read();
        if (prefs.theme === "System") {
            applyToDocument(prefs);
        }
    });

